@Testcontainers @ActiveProfiles("test")
@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT,properties={"email.delivery.mode=resend","email.delivery.worker-enabled=false","resend.api-key=synthetic-test-only","resend.from=ANITEC <mail@notifications.vitalwatch.space>","identity.password-recovery.enabled=true"})
class EmailOutboxTests {
 @Container @ServiceConnection static PostgreSQLContainer<?> postgres=new PostgreSQLContainer<>("postgres:16-alpine");
 static final String encryption=EmailCryptoSettingsTests.key(),hmac=EmailCryptoSettingsTests.key();
 @DynamicPropertySource static void config(DynamicPropertyRegistry r){r.add("email.delivery.encryption-key",()->encryption);r.add("identity.password-recovery.hmac-key",()->hmac);}
 static class Time extends Clock {final AtomicReference<Instant> now=new AtomicReference<>(Instant.now());public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId z){return this;}public Instant instant(){return now.get();}void advance(long seconds){now.updateAndGet(n->n.plusSeconds(seconds));}}
 static class Queue implements PasswordRecoveryWorkQueue {final java.util.Queue<Runnable> jobs=new ConcurrentLinkedQueue<>();public void submit(Runnable r){jobs.add(r);}void drain(){Runnable r;while((r=jobs.poll())!=null)r.run();}}
 static class Server implements AutoCloseable {
  final HttpServer server;final ExecutorService executor=Executors.newCachedThreadPool();
  final List<String> payloads=new CopyOnWriteArrayList<>(),keys=new CopyOnWriteArrayList<>();
  volatile int status=200;volatile String response="{}",retry;volatile Runnable inside=()->{};
  Server()throws Exception{server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.setExecutor(executor);server.createContext("/emails",x->{payloads.add(new String(x.getRequestBody().readAllBytes(),java.nio.charset.StandardCharsets.UTF_8));keys.add(x.getRequestHeaders().getFirst("Idempotency-Key"));try{inside.run();if(retry!=null)x.getResponseHeaders().add("Retry-After",retry);byte[] bytes=response.getBytes(java.nio.charset.StandardCharsets.UTF_8);x.sendResponseHeaders(status,bytes.length);x.getResponseBody().write(bytes);}finally{x.close();}});server.start();}
  public void close(){server.stop(0);executor.shutdownNow();}
 }
 @TestConfiguration static class Config {
  @Bean @Primary Time outboxTime(){return new Time();}
  @Bean @Primary Queue intake(){return new Queue();}
  @Bean(destroyMethod="close") Server provider()throws Exception{return new Server();}
  @Bean @Primary ResendEmailSender simulatedHttpTransport(Server server,Environment e){return new ResendEmailSender("synthetic-test-only","ANITEC <mail@notifications.vitalwatch.space>",e,true,1000,1000,URI.create("http://127.0.0.1:"+server.server.getAddress().getPort()));}
 }
 @Autowired IdentityService identity;@Autowired AccountRepository accounts;@Autowired JdbcTemplate jdbc;
 @Autowired EmailOutboxWorker worker;@Autowired JdbcSecurityEmailOutbox outbox;@Autowired EmailDeliverySettings settings;
 @Autowired ResendEmailSender sender;@Autowired PlatformTransactionManager manager;@Autowired Environment env;
 @Autowired Time clock;@Autowired Queue queue;@Autowired Server server;@Autowired PasswordRecoveryService recovery;
 @Autowired PasswordRecoveryRepository recoveries;@Autowired TestRestTemplate http;
 @BeforeEach void prepare(){jdbc.update("DELETE FROM identity_email_outbox");jdbc.update("UPDATE identity_email_delivery_gate SET paused_until='-infinity',error_category=NULL");clock.now.set(Instant.now().truncatedTo(java.time.temporal.ChronoUnit.MICROS));queue.jobs.clear();server.payloads.clear();server.keys.clear();server.status=200;server.response="{\"id\":\""+UUID.randomUUID()+"\"}";server.retry=null;server.inside=()->{};}
 String pending(){String e=UUID.randomUUID()+"@example.invalid";assertThat(identity.register(new IdentityService.RegisterCommand("Test","Outbox",e,"Initial-Password1!",Role.GANADERO)).emailDelivery()).isEqualTo("UNCONFIRMED");return e;}
 Account account(String e){return accounts.findByEmail(e).orElseThrow();}
 String active(){String e=pending();identity.verifyEmail(e,account(e).getVerificationCode());worker.cleanup();jdbc.update("DELETE FROM identity_email_outbox");return e;}
 Map<String,Object> job(){return jdbc.queryForMap("SELECT * FROM identity_email_outbox");}
 String state(){return (String)job().get("state");}
 void retryReady(){clock.now.set(((Timestamp)job().get("next_attempt_at")).toInstant());}
 void issueRecovery(String e){recovery.request(e);queue.drain();}
 @Test void registrationCommitsEmissionAndExactlyOneEncryptedJob(){String e=pending();var a=account(e);assertThat(state()).isEqualTo("PENDING");assertThat(job().get("account_id")).isEqualTo(a.getId());assertThat(job().keySet()).doesNotContain("email","code","html","text");assertThat(new String((byte[])job().get("ciphertext"),java.nio.charset.StandardCharsets.UTF_8)).doesNotContain(e,a.getVerificationCode());assertThat(server.payloads).isEmpty();}
 @Test void rollbackDoesNotKeepAccountOrJob(){String e=UUID.randomUUID()+"@example.invalid";new TransactionTemplate(manager).executeWithoutResult(t->{identity.register(new IdentityService.RegisterCommand("Test","Rollback",e,"Initial-Password1!",Role.GANADERO));t.setRollbackOnly();});assertThat(accounts.findByEmail(e)).isEmpty();assertThat(jdbc.queryForObject("SELECT count(*) FROM identity_email_outbox",Integer.class)).isZero();}
 @Test void duplicateStagingKeepsOneImmutableLogicalMessage(){String e=pending();var before=job();new TransactionTemplate(manager).executeWithoutResult(t->outbox.verification(account(e)));var after=job();assertThat(after.get("id")).isEqualTo(before.get("id"));assertThat((byte[])after.get("ciphertext")).isEqualTo((byte[])before.get("ciphertext"));}
 @Test void mandatoryTransactionRejectsUncoordinatedStaging(){String e=pending();assertThatThrownBy(()->outbox.verification(account(e))).isInstanceOf(IllegalTransactionStateException.class);}
 @Test void committedJobCanBeRecoveredByNewWorkerInstance(){pending();var restarted=new EmailOutboxWorker(jdbc,settings,sender,clock,manager,env);assertThat(restarted.runOne()).isTrue();assertThat(state()).isEqualTo("ACCEPTED");assertThat(server.payloads).hasSize(1);}
 @Test void failedHttpRetryRetainsCodePayloadKeyExpiryAndQuota(){String e=pending();var a=account(e);var before=job();server.status=503;server.response="{}";assertThat(worker.runOne()).isTrue();assertThat(state()).isEqualTo("RETRY_WAIT");retryReady();server.status=200;server.response="{\"id\":\""+UUID.randomUUID()+"\"}";worker.runOne();assertThat(state()).isEqualTo("ACCEPTED");assertThat(server.payloads).hasSize(2);assertThat(server.payloads.get(0)).isEqualTo(server.payloads.get(1)).contains(a.getVerificationCode());assertThat(server.keys.get(0)).isEqualTo(server.keys.get(1));assertThat(job().get("expires_at")).isEqualTo(before.get("expires_at"));assertThat(account(e).getVerificationResends()).isEqualTo(a.getVerificationResends());assertThat(account(e).getVerificationAttempts()).isEqualTo(a.getVerificationAttempts());}
 @Test void twoWorkersCannotClaimSameJob()throws Exception{pending();var start=new CyclicBarrier(2);try(var pool=Executors.newFixedThreadPool(2)){var a=pool.submit(()->{start.await();return worker.claim();});var b=pool.submit(()->{start.await();return worker.claim();});var claims=Arrays.asList(a.get(10,TimeUnit.SECONDS),b.get(10,TimeUnit.SECONDS));assertThat(claims.stream().filter(Objects::nonNull).count()).isEqualTo(1);assertThat(job().get("attempts")).isEqualTo(1);}}
 @Test void expiredClaimIsRecoverableAndOldWorkerIsFenced(){pending();var first=worker.claim();clock.advance(61);var second=worker.claim();assertThat(second.owner()).isNotEqualTo(first.owner());assertThat(worker.finish(first,new ResendEmailSender.Result(ResendEmailSender.Kind.ACCEPTED,UUID.randomUUID(),null,"ACCEPTED"))).isFalse();assertThat(worker.finish(second,new ResendEmailSender.Result(ResendEmailSender.Kind.ACCEPTED,UUID.randomUUID(),null,"ACCEPTED"))).isTrue();assertThat(job().get("attempts")).isEqualTo(2);}
 @Test void expiredClaimCannotRecordResultBeforeAnotherWorkerArrives(){pending();var c=worker.claim();clock.advance(61);assertThat(worker.finish(c,new ResendEmailSender.Result(ResendEmailSender.Kind.ACCEPTED,UUID.randomUUID(),null,"ACCEPTED"))).isFalse();assertThat(state()).isEqualTo("PROCESSING");}
 @Test void httpDoesNotHoldJobOrAccountLocks(){String e=pending();AtomicBoolean free=new AtomicBoolean();server.inside=()->new TransactionTemplate(manager).executeWithoutResult(t->{jdbc.queryForList("SELECT id FROM identity_email_outbox FOR UPDATE NOWAIT");jdbc.queryForList("SELECT id FROM identity_accounts WHERE id=? FOR UPDATE NOWAIT",account(e).getId());free.set(true);});worker.runOne();assertThat(free).isTrue();assertThat(state()).isEqualTo("ACCEPTED");}
 @Test void fiveTechnicalAttemptsMaximum(){pending();server.status=503;server.response="{}";for(int i=0;i<5;i++){assertThat(worker.runOne()).isTrue();if(i<4)retryReady();}assertThat(state()).isEqualTo("FAILED");assertThat(job().get("attempts")).isEqualTo(5);clock.advance(120);assertThat(worker.runOne()).isFalse();assertThat(server.payloads).hasSize(5);}
 @Test void uncertaintyAtLastAttemptIsTerminalUnknown(){pending();server.response="{}";for(int i=0;i<5;i++){worker.runOne();if(i<4)retryReady();}assertThat(state()).isEqualTo("UNKNOWN");assertThat(job().get("ciphertext")).isNull();}
 @Test void fiveLostClaimsCannotGenerateSixthSend(){pending();for(int i=0;i<5;i++){assertThat(worker.claim()).isNotNull();clock.advance(61);}assertThat(worker.claim()).isNull();assertThat(state()).isEqualTo("UNKNOWN");assertThat(job().get("attempts")).isEqualTo(5);}
 @Test void codeExpiryPreventsSendingWithoutDependingOnJanitor(){pending();clock.advance(601);assertThat(worker.runOne()).isFalse();assertThat(state()).isEqualTo("EXPIRED");assertThat(server.payloads).isEmpty();}
 @Test void retryAfterCodeExpiryIsNotScheduled(){pending();server.status=429;server.response="{}";server.retry="700";worker.runOne();assertThat(state()).isEqualTo("FAILED");assertThat(server.payloads).hasSize(1);}
 @Test void replacedVerificationCodeCancelsOldJob(){String e=pending();var old=(UUID)job().get("id");jdbc.update("UPDATE identity_accounts SET verification_sent_at=verification_sent_at-interval '61 seconds' WHERE id=?",account(e).getId());identity.resendVerificationCode(e);worker.cleanup();assertThat(jdbc.queryForObject("SELECT state FROM identity_email_outbox WHERE id=?",String.class,old)).isEqualTo("CANCELLED");assertThat(jdbc.queryForObject("SELECT count(*) FROM identity_email_outbox WHERE state='PENDING'",Integer.class)).isEqualTo(1);worker.runOne();assertThat(server.payloads).hasSize(1);}
 @Test void consumedVerificationIsIneligible(){String e=pending();identity.verifyEmail(e,account(e).getVerificationCode());assertThat(worker.runOne()).isFalse();assertThat(state()).isEqualTo("CANCELLED");assertThat(server.payloads).isEmpty();}
 @Test void exhaustedAttemptsAreIneligible(){String e=pending();jdbc.update("UPDATE identity_accounts SET verification_attempts=5 WHERE id=?",account(e).getId());assertThat(worker.runOne()).isFalse();assertThat(state()).isEqualTo("CANCELLED");}
 @Test void suspendedAccountIsIneligible(){String e=pending();jdbc.update("UPDATE identity_accounts SET status='SUSPENDIDA' WHERE id=?",account(e).getId());assertThat(worker.runOne()).isFalse();assertThat(state()).isEqualTo("CANCELLED");}
 @Test void acceptedPayloadIsErasedAndMetadataRetainedThenPurged(){pending();worker.runOne();assertThat(state()).isEqualTo("ACCEPTED");assertThat(job().get("ciphertext")).isNull();assertThat(job().get("nonce")).isNull();assertThat(job().get("provider_id")).isNotNull();clock.advance(14*86400-1);worker.cleanup();assertThat(jdbc.queryForObject("SELECT count(*) FROM identity_email_outbox",Integer.class)).isEqualTo(1);clock.advance(2);worker.cleanup();assertThat(jdbc.queryForObject("SELECT count(*) FROM identity_email_outbox",Integer.class)).isZero();}
 @Test void terminalJobsCannotBeReactivatedInSql(){pending();worker.runOne();assertThatThrownBy(()->jdbc.update("UPDATE identity_email_outbox SET state='PENDING'" )).isInstanceOf(org.springframework.dao.DataAccessException.class);}
 @Test void payloadAndExpiryCannotBeChangedInSql(){pending();assertThatThrownBy(()->jdbc.update("UPDATE identity_email_outbox SET expires_at=expires_at+interval '1 second'" )).isInstanceOf(org.springframework.dao.DataAccessException.class);assertThatThrownBy(()->jdbc.update("UPDATE identity_email_outbox SET ciphertext=decode('1234','hex')" )).isInstanceOf(org.springframework.dao.DataAccessException.class);}
 @Test void accountForeignKeyAndEmissionUniquenessAreEnforced(){String e=pending();assertThatThrownBy(()->jdbc.update("UPDATE identity_email_outbox SET account_id=?",UUID.randomUUID())).isInstanceOf(org.springframework.dao.DataAccessException.class);new TransactionTemplate(manager).executeWithoutResult(t->outbox.verification(account(e)));assertThat(jdbc.queryForObject("SELECT count(*) FROM identity_email_outbox",Integer.class)).isEqualTo(1);}
 @Test void invalidIdempotencyRequestIsTerminalAndNotRetried(){pending();server.status=409;server.response="{\"name\":\"invalid_idempotent_request\"}";worker.runOne();assertThat(state()).isEqualTo("FAILED");assertThat(job().get("error_category")).isEqualTo("IDEMPOTENCY_MISMATCH");assertThat(worker.runOne()).isFalse();}
 @Test void concurrentIdempotencyResponseSchedulesSameKey(){pending();server.status=409;server.response="{\"name\":\"concurrent_idempotent_requests\"}";worker.runOne();assertThat(state()).isEqualTo("RETRY_WAIT");retryReady();worker.runOne();assertThat(server.keys).hasSize(2);assertThat(server.keys.get(0)).isEqualTo(server.keys.get(1));}
 @Test void configurationFailurePausesOtherJobsAcrossWorkers(){pending();server.status=401;server.response="{}";worker.runOne();assertThat(state()).isEqualTo("RETRY_WAIT");assertThat(worker.claim()).isNull();assertThat(jdbc.queryForObject("SELECT paused_until>? FROM identity_email_delivery_gate",Boolean.class,Timestamp.from(clock.instant()))).isTrue();}
 @Test void quotaFailurePausesGloballyWithoutExtendingCode(){pending();var expires=job().get("expires_at");server.status=429;server.response="{\"name\":\"daily_quota_exceeded\"}";worker.runOne();assertThat(state()).isEqualTo("FAILED");assertThat(job().get("expires_at")).isEqualTo(expires);assertThat(worker.claim()).isNull();}
 @Test void passwordRecoveryEmissionAndJobAreAtomicAndRemainPrivate(){String e=active();var r=http.postForEntity("/api/v1/auth/password-recovery/request",Map.of("email",e),JsonNode.class);assertThat(r.getStatusCode().value()).isEqualTo(202);assertThat(r.getBody().has("data")).isFalse();queue.drain();assertThat(recoveries.find(account(e).getId())).isPresent();assertThat(state()).isEqualTo("PENDING");assertThat(job().get("purpose")).isEqualTo("PASSWORD_RECOVERY");assertThat(server.payloads).isEmpty();worker.runOne();assertThat(state()).isEqualTo("ACCEPTED");}
 @Test void recoveryRetryNeverConsumesAdditionalQuota(){String e=active();issueRecovery(e);var before=recoveries.find(account(e).getId()).orElseThrow();server.status=503;server.response="{}";worker.runOne();retryReady();worker.runOne();var after=recoveries.find(account(e).getId()).orElseThrow();assertThat(after.emissionId()).isEqualTo(before.emissionId());assertThat(after.emissions()).isEqualTo(before.emissions());assertThat(after.expiresAt()).isEqualTo(before.expiresAt());assertThat(after.verifier()).isEqualTo(before.verifier());assertThat(server.payloads.get(0)).isEqualTo(server.payloads.get(1));}
 @Test void replacedRecoveryIsIneligible(){String e=active();issueRecovery(e);UUID old=(UUID)job().get("id");clock.advance(60);issueRecovery(e);worker.cleanup();assertThat(jdbc.queryForObject("SELECT state FROM identity_email_outbox WHERE id=?",String.class,old)).isEqualTo("CANCELLED");}
 @Test void consumedRecoveryCancelsUnsentJobAndRevokesSessions()throws Exception{String e=active();var session=identity.login(e,"Initial-Password1!");issueRecovery(e);var j=job();String payload=new EmailOutboxCipher(settings.encryptionKey()).decrypt((UUID)j.get("id"),(UUID)j.get("emission_id"),(String)j.get("purpose"),new EmailOutboxCipher.Envelope((byte[])j.get("nonce"),(byte[])j.get("ciphertext")));var text=new ObjectMapper().readTree(payload).path("text").asText();var match=java.util.regex.Pattern.compile("[0-9]{6}").matcher(text);assertThat(match.find()).isTrue();recovery.confirm(e,match.group(),"Updated-Password2!");assertThat(worker.runOne()).isFalse();assertThat(state()).isEqualTo("CANCELLED");assertThat(jdbc.queryForObject("SELECT count(*) FROM identity_sessions WHERE account_id=? AND revoked_at IS NULL",Integer.class,session.accountId())).isZero();}
 @Test void recoveryForUnknownPendingOrSuspendedDoesNotQueueMessage(){String p=pending();jdbc.update("DELETE FROM identity_email_outbox");String suspended=active();jdbc.update("UPDATE identity_accounts SET status='SUSPENDIDA' WHERE id=?",account(suspended).getId());for(String e:List.of(p,suspended,"unknown@example.invalid")){issueRecovery(e);}assertThat(jdbc.queryForObject("SELECT count(*) FROM identity_email_outbox",Integer.class)).isZero();}
 @Test void queueShutdownDoesNotDiscardCommittedEmailJob(){String e=active();issueRecovery(e);queue.jobs.clear();var restarted=new EmailOutboxWorker(jdbc,settings,sender,clock,manager,env);assertThat(restarted.runOne()).isTrue();assertThat(state()).isEqualTo("ACCEPTED");}
 @Test void stoppingWorkerDoesNotClaimWork(){pending();var stopped=new EmailOutboxWorker(jdbc,settings,sender,clock,manager,env);stopped.stop();assertThat(stopped.runOne()).isFalse();assertThat(state()).isEqualTo("PENDING");}
 @Test void runningWorkerInsideTransactionIsRejected(){pending();assertThatThrownBy(()->new TransactionTemplate(manager).execute(t->worker.runOne())).isInstanceOf(IllegalStateException.class);assertThat(state()).isEqualTo("PENDING");}
 @Test void stagingFailureRollsBackEmissionAndSanitizesSqlDetails(){String e=UUID.randomUUID()+"@example.invalid";jdbc.execute("ALTER TABLE identity_email_outbox ADD CONSTRAINT email_test_reject CHECK(false) NOT VALID");try{assertThatThrownBy(()->identity.register(new IdentityService.RegisterCommand("Test","Rollback",e,"Initial-Password1!",Role.GANADERO))).isInstanceOfSatisfying(DomainException.class,f->{assertThat(f.errorCode()).isEqualTo("EMAIL_UNAVAILABLE");assertThat(f.getCause()).isNull();assertThat(f.getMessage()).doesNotContain(e,"ciphertext","Initial-Password1!");});assertThat(accounts.findByEmail(e)).isEmpty();assertThat(jdbc.queryForObject("SELECT count(*) FROM identity_email_outbox",Integer.class)).isZero();}finally{jdbc.execute("ALTER TABLE identity_email_outbox DROP CONSTRAINT email_test_reject");}}

 @Test void recoveryStagingFailureDoesNotConsumeQuotaOrLeaveCode(){String e=active();jdbc.execute("ALTER TABLE identity_email_outbox ADD CONSTRAINT email_test_reject CHECK(false) NOT VALID");try{issueRecovery(e);assertThat(recoveries.find(account(e).getId())).isEmpty();assertThat(jdbc.queryForObject("SELECT count(*) FROM identity_email_outbox",Integer.class)).isZero();}finally{jdbc.execute("ALTER TABLE identity_email_outbox DROP CONSTRAINT email_test_reject");}}
 @Test void wrongDecryptionKeyFailsClosedWithoutSending(){pending();var config=new org.springframework.mock.env.MockEnvironment().withProperty("email.delivery.mode","resend").withProperty("resend.api-key","synthetic-only").withProperty("resend.from","ANITEC <mail@notifications.vitalwatch.space>").withProperty("EMAIL_OUTBOX_ENCRYPTION_KEY",EmailCryptoSettingsTests.key());var wrong=new EmailOutboxWorker(jdbc,new EmailDeliverySettings(config),sender,clock,manager,env);assertThat(wrong.runOne()).isTrue();assertThat(state()).isEqualTo("FAILED");assertThat(job().get("error_category")).isEqualTo("ENVELOPE_INVALID");assertThat(job().get("ciphertext")).isNull();assertThat(server.payloads).isEmpty();}

 @Test void extremeRetryAfterCannotOverflowOrPermitEarlyRetry(){pending();server.status=429;server.response="{}";server.retry=Long.toString(Long.MAX_VALUE);assertThat(worker.runOne()).isTrue();assertThat(state()).isEqualTo("FAILED");assertThat(worker.runOne()).isFalse();assertThat(server.payloads).hasSize(1);}

 @Test void resendStagingFailureRollsBackCodeQuotaAndEmissionIdentity(){String e=pending();UUID id=account(e).getId();jdbc.update("UPDATE identity_accounts SET verification_sent_at=verification_sent_at-interval '61 seconds' WHERE id=?",id);var before=account(e);UUID emission=jdbc.queryForObject("SELECT verification_emission_id FROM identity_accounts WHERE id=?",UUID.class,id);jdbc.execute("ALTER TABLE identity_email_outbox ADD CONSTRAINT email_test_reject CHECK(false) NOT VALID");try{assertThatThrownBy(()->identity.resendVerificationCode(e)).isInstanceOfSatisfying(DomainException.class,f->assertThat(f.errorCode()).isEqualTo("EMAIL_UNAVAILABLE"));var after=account(e);assertThat(after.getVerificationCode()).isEqualTo(before.getVerificationCode());assertThat(after.getVerificationResends()).isEqualTo(before.getVerificationResends());assertThat(after.getVerificationExpiresAt()).isEqualTo(before.getVerificationExpiresAt());assertThat(jdbc.queryForObject("SELECT verification_emission_id FROM identity_accounts WHERE id=?",UUID.class,id)).isEqualTo(emission);assertThat(jdbc.queryForObject("SELECT count(*) FROM identity_email_outbox",Integer.class)).isEqualTo(1);}finally{jdbc.execute("ALTER TABLE identity_email_outbox DROP CONSTRAINT email_test_reject");}}

}
